import log from '~/lib/log';
import { Splide } from '@splidejs/splide';

function mainProduct(productData = {}) {
  log.debug('mainProduct FUNCTION CALLED', productData);
  return {
    mediaCount: productData.mediaCount || 0,
    variantId: productData.variantId || null,
    addToCartText: productData.addToCartText || 'Add to cart',
    soldOutText: productData.soldOutText || 'Sold out',
    quantityValue: productData.quantityValue || 1,
    selectedColor: productData.selectedColor || '',
    selectedOtherOption: productData.selectedOtherOption || '',
    selectedVariantTitle: productData.selectedVariantTitle || '',
    selectedVariantAvailable: productData.selectedVariantAvailable || false,
    variants: productData.variants || [],
    colorOptionPosition: productData.colorOptionPosition || 0,
    otherOptionPosition: productData.otherOptionPosition || 0,
    selectedColorImage: productData.selectedColorImage || '',
    selectedColorName: productData.selectedColorName || '',
    selectedVariant: null,
    // eslint-disable-next-line no-template-curly-in-string
    moneyFormat: productData.moneyFormat || '${{amount}}',

    init() {
      log.debug('mainProduct INIT called');

      // Check URL for variant parameter and set initial variant
      const urlParams = new URLSearchParams(window.location.search);
      const variantIdFromUrl = urlParams.get('variant');

      if (variantIdFromUrl) {
        // Find the variant from URL parameter
        const variantFromUrl = this.variants.find((v) => v.id === parseInt(variantIdFromUrl, 10));

        if (variantFromUrl) {
          // Set the options based on the URL variant
          if (this.colorOptionPosition > 0) {
            this.selectedColor = variantFromUrl.options[this.colorOptionPosition - 1];
            const colorValue = this.variants.find((v) => v.id === variantFromUrl.id);

            if (colorValue) {
              // You might need to get the color swatch info here if needed
            }
          }

          if (this.otherOptionPosition > 0) {
            this.selectedOtherOption = variantFromUrl.options[this.otherOptionPosition - 1];
          }
        }
      }

      // Initialize the selected variant on component mount
      this.updateSelectedVariant();

      // Watch for price changes
      this.$watch('selectedVariant', (variant) => {
        if (variant && variant.price) {
          log.debug('$watch triggered - Variant price changed');
          // Update URL with variant parameter
          this.updateUrl();
        }
      });
    },

    updateUrl() {
      if (this.variantId) {
        const url = new URL(window.location.href);

        url.searchParams.set('variant', this.variantId);
        window.history.replaceState({}, '', url);
      }
    },

    initSplide() {
      // Use querySelector since x-ref is in a child snippet
      // Add a small delay to ensure DOM is ready
      this.$nextTick(() => {
        const element = this.$el.querySelector('.splide');

        if (!element) {
          log.warn('Splide element not found');
          return;
        }

        const slideCount = element.querySelectorAll('.splide__slide').length;

        log.debug(`Found ${slideCount} slides`);

        // Disable slider features if only one slide
        const isSingleSlide = slideCount === 1;

        this.splide = new Splide(element, {
          type: isSingleSlide ? 'slide' : 'loop',
          perPage: 1,
          perMove: 1,
          gap: '1rem',
          pagination: false,
          arrows: false,
          drag: !isSingleSlide, // Disable drag/swipe for single slide
          swipe: !isSingleSlide, // Disable swipe for single slide
          wheel: false, // Disable mouse wheel navigation
        });
        this.splide.mount();
        log.debug('Splide initialized successfully');
      });
    },

    get hasPrevious() {
      return this.mediaCount > 1;
    },
    get hasNext() {
      return this.mediaCount > 1;
    },

    goToPrevious() {
      if (this.splide && this.hasPrevious) {
        this.splide.go('<');
      }
    },

    goToNext() {
      if (this.splide && this.hasNext) {
        this.splide.go('>');
      }
    },

    selectColor(color = '', image = '', colorName = '') {
      this.selectedColor = color;
      this.selectedColorImage = image;
      this.selectedColorName = colorName;

      // Auto-select first available size/option for this color
      if (this.otherOptionPosition > 0) {
        // Find first available variant with this color
        for (const variant of this.variants) {
          const variantColor = variant.options[this.colorOptionPosition - 1];
          if (variantColor === color && variant.available) {
            // Select the size/option from this variant
            this.selectedOtherOption = variant.options[this.otherOptionPosition - 1];
            break;
          }
        }
      }

      // Reset quantity to 1 when variant changes
      this.quantityValue = 1;

      this.updateSelectedVariant();
    },

    selectOtherOption(option) {
      this.selectedOtherOption = option;
      log.debug('Variants', this.variants);
      this.selectedUnavailableColor = this.variants.filter((variant) => {
        const variantColor = variant.options[this.otherOptionPosition - 1];
        return variantColor === this.selectedOtherOption && !variant.available;
      });

      // Reset quantity to 1 when variant changes
      this.quantityValue = 1;

      this.updateSelectedVariant();
    },

    isOptionAvailable(optionPosition, optionValue) {
      // Check if this option value is available with the currently selected other options
      for (const variant of this.variants) {
        // Check if this variant has the option value we're looking for
        if (variant.options[optionPosition] !== optionValue) {
          continue;
        }

        // Check color option if it exists and is selected
        if (this.colorOptionPosition > 0 && this.selectedColor) {
          const colorMatches = variant.options[this.colorOptionPosition - 1] === this.selectedColor;
          if (!colorMatches) {
            continue;
          }
        }

        // If we found a matching variant that's available, return true
        if (variant.available) {
          return true;
        }
      }

      // No available variant found with this option value
      return false;
    },

    updateSelectedVariant() {
      // Find the variant that matches the selected options
      for (const variant of this.variants) {
        let colorMatches = true;
        let otherOptionMatches = true;

        // Check color option if it exists
        if (this.colorOptionPosition > 0) {
          colorMatches = variant.options[this.colorOptionPosition - 1] === this.selectedColor;
        }

        // Check other option if it exists
        if (this.otherOptionPosition > 0) {
          otherOptionMatches = variant.options[this.otherOptionPosition - 1] === this.selectedOtherOption;
        }

        // Only match if ALL applicable options match
        if (colorMatches && otherOptionMatches) {
          // Create a new object to ensure Alpine reactivity
          this.selectedVariant = {
            id: variant.id,
            title: variant.title,
            available: variant.available,
            price: variant.price,
            compare_at_price: variant.compare_at_price,
            options: variant.options,
          };
          this.variantId = variant.id;
          this.selectedVariantTitle = variant.title;
          this.selectedVariantAvailable = variant.available;
          log.debug('Selected variant:', this.selectedVariant);
          return;
        }
      }

      log.warn('No matching variant found for:', {
        color: this.selectedColor,
        otherOption: this.selectedOtherOption,
      });
    },

    formatMoney(cents) {
      // Format money using Shopify's money format
      // Convert cents to dollars with 2 decimal places
      const dollars = (cents / 100).toFixed(2);
      // Replace {{amount}} or {{amount_with_comma_separator}} in the format string
      return this.moneyFormat
        .replace(/\{\{\s*amount\s*\}\}/, dollars)
        .replace(/\{\{\s*amount_with_comma_separator\s*\}\}/, dollars.replace('.', ','));
    },

    get currentPrice() {
      return this.selectedVariant && this.selectedVariant.price
        ? this.formatMoney(this.selectedVariant.price)
        : '';
    },

    get currentComparePrice() {
      return this.selectedVariant && this.selectedVariant.compare_at_price
        ? this.formatMoney(this.selectedVariant.compare_at_price)
        : '';
    },

    get showComparePrice() {
      return this.selectedVariant
        && this.selectedVariant.compare_at_price
        && this.selectedVariant.compare_at_price > this.selectedVariant.price;
    },

  };
}

// Make mainProduct available globally for Alpine.js

window.mainProduct = mainProduct;
